import { Fetch } from 'metaowl'

Fetch.configure({
  baseUrl: 'https://api.example.com',
  headers: {
    'Authorization': 'Bearer token'
  }
})

// GET request
const users = await Fetch.url('/users', 'GET')

// POST request
const newUser = await Fetch.url('/users', 'POST', { name: 'John' })

// PUT request
await Fetch.url('/users/1', 'PUT', { name: 'Jane' })

// DELETE request
await Fetch.url('/users/1', 'DELETE')

import { Component, useState } from '@odoo/owl'
import { Meta, Fetch as FetchAPI } from 'metaowl'

export default class Fetch extends Component {
  static template = 'Fetch'
  static components = {}

  setup() {
    Meta.title('Fetch API - MetaOWL')
    Meta.description(
      'Learn how to use the Fetch API for HTTP requests in MetaOWL.',
    )
    this.state = useState({
      users: [],
      loading: true,
      error: null,
    })
    this.fetchUsers()
  }

  async fetchUsers() {
    try {
      this.state.users = await FetchAPI.url('https://jsonplaceholder.typicode.com/users')
    } catch (e) {
      this.state.error = e?.message || 'Failed to load'
    } finally {
      this.state.loading = false
    }
  }
}

import { Fetch, Cache } from 'metaowl'

async function getUsers() {
  const cacheKey = 'users'
  const cached = await Cache.get(cacheKey)
  if (cached) return cached

  const users = await Fetch.url('/users', 'GET')
  await Cache.set(cacheKey, users)
  return users
}
